export const defaultUserMetadata = {
    onboardingFlow: {
        allowed: false,
        extensionSent: true,
        mobileAppSent: true,
        language: null,
    },
    rate: {
        ios: undefined,
        android: undefined,
        chromeExtension: undefined,
        edgeExtension: undefined,
        safariExtension: undefined,
    },
    lastUpdated: 0,
};
export const mergeUserMetadata = (md1, md2) => {
    return {
        ...md1,
        ...md2,
        rate: {
            ...md1.rate,
            ...md2.rate,
        },
        onboardingFlow: {
            ...md1.onboardingFlow,
            ...md2.onboardingFlow,
        },
    };
};
export const mapUserMetadata = (metadata) => {
    return mergeUserMetadata(defaultUserMetadata, metadata);
};
