export const parseJson = (text) => {
    try {
        return {
            success: true,
            value: JSON.parse(text),
        };
    }
    catch (e) {
        return {
            success: false,
            errorCode: 'JSON_PARSE_ERROR',
            reason: 'Unable to parse the JSON string',
            extra: {
                error: e,
                text,
            },
        };
    }
};
